function prefixeCommun(tab) {
    if (tab.length === 0) return '';
    const first = tab[0];
    let prefix = '';
    for (let i = 0; i < first.length; i++) {
        const char = first[i];
        let allMatch = true;
        for (let j = 1; j < tab.length; j++) {
            const str = tab[j];
            if (i >= str.length || str[i] !== char) {
                allMatch = false;
                break;
            }
        }
        if (allMatch) {
            prefix += char;
        } else {
            break;
        }
    }
    return prefix;
}
```

