function medianeDeuxTries(a, b) {
    const n = a.length;
    const m = b.length;
    const total = n + m;
    const k = Math.floor((total - 1) / 2);

    function getKth(a, b, k) {
        if (a.length === 0) return b[k];
        if (b.length === 0) return a[k];

        if (a[0] > b[k]) {
            return getKth(a.slice(1), b, k - 1);
        }
        if (a[k] > b[b.length - 1]) {
            return getKth(a, b.slice(0, k + 1), k);
        }
        return a[k];
    }

    return getKth(a, b, k);
}
```

